mapper.update:
UPDATE marketing_task
SET status = 7,
    next_round_at = NULL,
    finished_at = COALESCE(finished_at, #{now}),
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status IN (1, 2, 5)
  AND task_end_at IS NOT NULL
  AND task_end_at <= #{now}

UPDATE marketing_task
SET status = 1,
    next_round_at = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status = 2
  AND task_start_at IS NOT NULL
  AND task_start_at > #{now}

UPDATE marketing_task
SET next_round_at = #{nextRoundAt},
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status = 2
  AND next_round_at IS NOT NULL
  AND next_round_at <= #{now}
  AND (task_end_at IS NULL OR task_end_at > #{now})

UPDATE marketing_task
SET target_group_count = target_group_count + 1,
    updated_at = #{now}
WHERE id = #{taskId}

mapper.select:
SELECT a.id AS accountId, a.ws_phone AS accountPhone, g.id AS groupLinkId, p.group_jid AS groupJid, g.link_url AS groupLinkUrl, COALESCE(NULLIF(TRIM(g.group_name), ''), p.wa_subject) AS groupName FROM account a JOIN account_state s ON s.account_id = a.id JOIN group_link g ON g.id = #{groupLinkId} AND g.deleted_at IS NULL AND g.membership_state IN (2, 3) JOIN group_link_preview p ON p.group_link_id = g.id LEFT JOIN group_link_health h ON h.group_link_id = g.id LEFT JOIN account_group_baseline b ON b.account_id = a.id AND a.group_baseline_state = 2 WHERE a.id = #{accountId} AND a.account_group_id = #{accountGroupId} AND a.deleted_at IS NULL AND s.login_state = 1 AND s.account_state IN
#{accountState}
AND a.protocol_account_id IS NOT NULL AND TRIM(a.protocol_account_id) <> '' AND a.group_baseline_state IN (2, 3) AND (s.risk_status IS NULL OR s.risk_status = 1) AND s.mute_status IS NULL AND p.group_jid IS NOT NULL AND TRIM(p.group_jid) <> '' AND (h.id IS NULL OR (COALESCE(h.is_banned, 0) = 0 AND (h.health_status IS NULL OR h.health_status = 1))) AND ( a.group_baseline_state <> 2 OR b.id IS NULL OR COALESCE(JSON_CONTAINS(b.baseline_group_jids, JSON_QUOTE(p.group_jid)), 0) = 0 ) LIMIT 1

SELECT a.id AS accountId, a.ws_phone AS accountPhone FROM account a JOIN account_state s ON s.account_id = a.id WHERE a.id = #{accountId} AND a.account_group_id = #{accountGroupId} AND a.deleted_at IS NULL AND s.login_state = 1 AND s.account_state IN
#{accountState}
AND a.protocol_account_id IS NOT NULL AND TRIM(a.protocol_account_id) <> '' AND a.group_baseline_state IN (2, 3) AND (s.risk_status IS NULL OR s.risk_status = 1) AND s.mute_status IS NULL LIMIT 1
